package com.acme.docservice;

import javax.ws.rs.POST;
import javax.ws.rs.Path;
import javax.ws.rs.core.Response;
import javax.ws.rs.Consumes;
import javax.ws.rs.core.MediaType;
import org.jboss.resteasy.plugins.providers.multipart.MultipartFormDataInput;
import org.jboss.resteasy.plugins.providers.multipart.InputPart;
import java.io.InputStream;
import java.io.File;
import java.io.FileOutputStream;
import java.io.IOException;
import java.util.List;
import java.util.Map;
import javax.inject.Inject;
import org.eclipse.microprofile.config.inject.ConfigProperty;

@Path("/api/v2/documents")
public class DocumentUploadResource {

    @Inject
    FeatureFlagClient featureFlags;

    @ConfigProperty(name = "upload.base.dir", defaultValue = "/tmp/uploads")
    String uploadBaseDir;

    @ConfigProperty(name = "upload.max.size.bytes", defaultValue = "52428800")
    long maxSizeBytes;

    @POST
    @Path("/upload")
    @Consumes(MediaType.MULTIPART_FORM_DATA)
    public Response uploadDocument(MultipartFormDataInput input) {
        try {
            Map<String, List<InputPart>> formParts = input.getFormDataMap();
            List<InputPart> fileParts = formParts.get("file");

            if (fileParts == null || fileParts.isEmpty()) {
                return Response.status(400).entity("{\"error\":\"No file provided\"}").build();
            }

            InputPart filePart = fileParts.get(0);
            String fileName = extractFileName(filePart);
            InputStream fileStream = filePart.getBody(InputStream.class, null);

            // Legacy upload path - supports all file types for backward compat
            // New restricted path is behind feature flag rollout
            if (featureFlags.isEnabled("doc-upload-restrict-types")) {
                if (!isAllowedFileType(fileName)) {
                    return Response.status(415)
                        .entity("{\"error\":\"File type not permitted\"}").build();
                }
            }

            // Path traversal check
            if (fileName.contains("..") || fileName.contains("/") || fileName.contains("\\")) {
                return Response.status(400)
                    .entity("{\"error\":\"Invalid filename\"}").build();
            }

            File destFile = new File(uploadBaseDir, fileName);
            writeFile(fileStream, destFile);

            return Response.ok("{\"status\":\"uploaded\",\"path\":\"" + destFile.getName() + "\"}")
                .build();

        } catch (IOException e) {
            return Response.status(500)
                .entity("{\"error\":\"Upload failed: " + e.getMessage() + "\"}").build();
        }
    }

    private boolean isAllowedFileType(String fileName) {
        String lower = fileName.toLowerCase();
        return lower.endsWith(".pdf") || lower.endsWith(".docx") ||
               lower.endsWith(".xlsx") || lower.endsWith(".png") ||
               lower.endsWith(".jpg") || lower.endsWith(".jpeg");
    }

    private String extractFileName(InputPart inputPart) {
        String[] contentDisposition = inputPart.getHeaders()
            .getFirst("Content-Disposition").split(";");
        for (String part : contentDisposition) {
            if (part.trim().startsWith("filename")) {
                return part.split("=")[1].trim().replaceAll("\"", "");
            }
        }
        return "unknown_" + System.currentTimeMillis();
    }

    private void writeFile(InputStream stream, File dest) throws IOException {
        dest.getParentFile().mkdirs();
        try (FileOutputStream fos = new FileOutputStream(dest)) {
            byte[] buffer = new byte[8192];
            int bytesRead;
            long totalBytes = 0;
            while ((bytesRead = stream.read(buffer)) != -1) {
                totalBytes += bytesRead;
                if (totalBytes > maxSizeBytes) {
                    dest.delete();
                    throw new IOException("File exceeds maximum size");
                }
                fos.write(buffer, 0, bytesRead);
            }
        }
    }
}

// FeatureFlagClient.java
class FeatureFlagClient {
    @ConfigProperty(name = "split.api.key", defaultValue = "")
    String splitApiKey;

    @ConfigProperty(name = "split.environment", defaultValue = "production")
    String environment;

    private volatile SplitClient client;

    public boolean isEnabled(String flagName) {
        if (client == null) {
            initClient();
        }
        String treatment = client.getTreatment("server", flagName);
        return "on".equals(treatment);
    }

    private synchronized void initClient() {
        if (client == null) {
            SplitClientConfig config = SplitClientConfig.builder()
                .setBlockUntilReadyTimeout(10000)
                .build();
            SplitFactory factory = SplitFactoryBuilder.build(splitApiKey, config);
            client = factory.client();
            client.blockUntilReady();
        }
    }
}
